   301:     /// Runs the pipeline for one request and seals the answer.
   302:     ///
   303:     /// [`headers::seal`] is applied here, once, on **every** path — success,
   304:     /// refusal, unknown route, and worker failure alike. That is what makes the
   305:     /// security headers total: a [`Response`] does not exist until routing has
   306:     /// chosen one, and it cannot leave this function unsealed.
   307:     async fn dispatch(&self, head: &RequestHead, body: &[u8], peer: SocketAddr) -> Response {
   308:         let answer = self.route_request(head, body, peer).await;
   309:         headers::seal(answer, self.api.guard().is_secure())
   310:     }
