   312:     /// Steps 2 through 7 of the pipeline for one request.
   313:     ///
   314:     /// Separated from [`ManagementService::dispatch`] so that the sealing
   315:     /// guarantee has exactly one call site to audit: this function is free to
   316:     /// return early from anywhere, because every early return still goes back
   317:     /// through [`ManagementService::dispatch`].
   318:     async fn route_request(&self, head: &RequestHead, body: &[u8], peer: SocketAddr) -> Response {
   319:         let guard = self.api.guard();
   320: 
   321:         // 2. Host, before routing, for every request without exception. A
   322:         //    rebinding attempt dies here, so it cannot produce a side effect on
   323:         //    any route — including the ones that change state.
   324:         if let Err(rejection) = guard.check_host(head) {
   325:             return refusal(rejection);
   326:         }
   327: 
   328:         // 3 and 4. Route and method.
   329:         let matched = route(head.target().path());
   330:         if !matched.accepts(head.method().as_str()) {
   331:             // A known route reached by an unknown method says so; an unknown
   332:             // route stays a 404 so a prober cannot enumerate the surface.
   333:             return if matched.rejects_method(head.method().as_str()) {
   334:                 response::method_not_allowed()
   335:             } else {
   336:                 response::not_found()
   337:             };
   338:         }
   339: 
   340:         // 5. Origin, for every unsafe method on every route.
   341:         if let Err(rejection) = guard.check_origin(head) {
   342:             return refusal(rejection);
   343:         }
   344: 
   345:         // 6 and 7. Session, CSRF, and the handler.
   346:         match matched {
   347:             Route::Healthz => match self.api.worker_health().await {
   348:                 // Classified once, then projected down to two tokens. The
   349:                 // reasons `Readiness` carries are not rendered here and have no
   350:                 // path to this response -- only the operator's startup log and
   351:                 // the authenticated route below can name them.
   352:                 Ok(health) => response::liveness(Liveness::from_readiness(
   353:                     super::Readiness::from_health(&health),
   354:                 )),
   355:                 Err(error) => response_for_worker_error(error),
   356:             },
   357:             Route::Login => match self.api.login(head, body, peer).await {
   358:                 Ok(response) => response,
   359:                 Err(rejection) => refusal(rejection),
   360:             },
   361:             Route::Logout => {
   362:                 // Both checks run before anything is revoked. A logout without a
   363:                 // CSRF token is an attacker's request, and revoking on it would
   364:                 // turn a cross-site request into a working denial of service.
   365:                 let Some(session) = self.api.authenticate(head).await else {
   366:                     return refusal(RequestRejection::NotAuthenticated);
   367:                 };
